{"version":3,"sources":["../scss/map.scss","map.css"],"names":[],"mappings":"AAIA;EACE,iBAAA;EACA,6BAAA;ACHF;;ADMA;EACE,aAAA;EACA,sBAAA;EACA,SAAA;ACHF;ADKE;EACE,kBAAA;EACA,kBAAA;ACHJ;ADII;EACE,kBAAA;EACA,MAAA;EACA,OAAA;EACA,WAAA;EACA,cAAA;EACA,WAAA;EACA,YAAA;EACA,yDAAA;ACFN;;ADOA;EACE,aAAA;EACA,sBAAA;EACA,SAAA;EACA,gBAAA;ACJF","file":"map.css","sourcesContent":["@import \"./variables\";\n@import \"./mixins\";\n\n\n.map {\n  padding-top: 20px;\n  border-top: 1px solid $gray;\n}\n\n.map__list {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n\n  & li {\n    padding-left: 20px;\n    position: relative;\n    &::before {\n      position: absolute;\n      top: 0;\n      left: 0;\n      content: \"\";\n      display: block;\n      width: 15px;\n      height: 15px;\n      background: url(../img/folder.gif) no-repeat center/cover;\n    }\n  }\n}\n\n.map__list-children {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  margin-top: 10px;\n}",".map {\n  padding-top: 20px;\n  border-top: 1px solid #D4D4D4;\n}\n\n.map__list {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n.map__list li {\n  padding-left: 20px;\n  position: relative;\n}\n.map__list li::before {\n  position: absolute;\n  top: 0;\n  left: 0;\n  content: \"\";\n  display: block;\n  width: 15px;\n  height: 15px;\n  background: url(../img/folder.gif) no-repeat center/cover;\n}\n\n.map__list-children {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  margin-top: 10px;\n}"]}: 10px;\n}"]}